      const html = readFileSync(indexPath, "utf8");
      for (const marker of ETY_HANDLER_MARKERS) {
        expect(html, `${name} missing ${marker}`).toContain(marker);
      }
      checked += 1;
    }
    expect(checked).toBeGreaterThan(0);
  });
});

